<section class="panel"><h2><i data-lucide="crown"></i> Best-Selling Items</h2><p>Top products over the past 7 days</p>@forelse($bestSellers as $item)@php $img=trim((string)($item->image ?? '')); $img=preg_replace('#^(?:/)?(?:storage/|public/)#','',$img); $imgUrl=$img ? \Illuminate\Support\Facades\Storage::disk('public')->url($img) : null; @endphp<div class="best-row">@if($imgUrl)<img class="best-img" src="{{ $imgUrl }}" alt="{{ $item->product_name }}">@else<div class="best-img" style="display:grid;place-items:center;color:#ffc979"><i data-lucide="coffee"></i></div>@endif<div class="best-content"><div class="best-title"><strong>{{ $item->product_name }}</strong><span>{{ $item->qty }} sold</span></div><div class="progress"><span style="width:{{ $bestSellers->first()->qty ? $item->qty/$bestSellers->first()->qty*100 : 0 }}%"></span></div></div></div>@empty<div class="empty">No best sellers to display yet.</div>@endforelse</section></div></div></main></div>
<script>
const notifRoutes={list:@json(route('admin.dashboard.notifications')),read:@json(route('admin.dashboard.notifications.read',['id'=>'__ID__'])),all:@json(route('admin.dashboard.notifications.read-all'))};
const csrf=document.querySelector('meta[name="csrf-token"]').content;
let notificationData=@json($notificationData);
const panel=document.getElementById('notifPanel'), bell=document.getElementById('bellBtn'), badge=document.getElementById('notifCount'), list=document.getElementById('notifList');
function renderNotifications(){badge.textContent=notificationData.unread;badge.hidden=!notificationData.unread;list.replaceChildren();if(!notificationData.items.length){const e=document.createElement('div');e.className='empty';e.textContent='No notifications yet.';list.append(e);return;}for(const item of notificationData.items){const row=document.createElement('div');row.className='notif-item'+(item.read?'':' unread');const title=document.createElement('strong');title.textContent=item.title;const message=document.createElement('p');message.textContent=item.message;const date=document.createElement('small');date.textContent=item.date;row.append(title,message,date);if(!item.read){const btn=document.createElement('button');btn.className='text-btn';btn.textContent='Mark as read';btn.style.display='block';btn.style.marginTop='7px';btn.addEventListener('click',()=>markRead(item.id,item.url));row.append(btn);}else if(item.url){const link=document.createElement('a');link.href=item.url;link.textContent='Open →';link.className='text-btn';link.style.display='block';row.append(link);}list.append(row);}}
async function request(url,method='GET'){const res=await fetch(url,{method,credentials:'same-origin',headers:{'Accept':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},cache:'no-store'});if(!res.ok)throw new Error('Request failed ('+res.status+'). Refresh and try again.');return res.json();}
async function refreshNotifications(){try{notificationData=await request(notifRoutes.list);renderNotifications();}catch(e){console.warn('Notifications:',e.message);}}
async function markRead(id,url){try{await request(notifRoutes.read.replace('__ID__',encodeURIComponent(id)),'PATCH');await refreshNotifications();if(url)window.location.assign(url);}catch(e){alert(e.message);}}
document.getElementById('markAll').addEventListener('click',async()=>{try{await request(notifRoutes.all,'PATCH');await refreshNotifications();}catch(e){alert(e.message);}});
bell.addEventListener('click',()=>{panel.hidden=!panel.hidden;bell.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)refreshNotifications();});document.addEventListener('click',e=>{if(!panel.contains(e.target)&&!bell.contains(e.target)){panel.hidden=true;bell.setAttribute('aria-expanded','false');}});
document.getElementById('menuBtn').addEventListener('click',()=>{
const mobile=window.matchMedia('(max-width:820px)').matches;
if(mobile){document.getElementById('sidebar').classList.toggle('open');document.getElementById('overlay').classList.toggle('show');}
else{const collapsed=document.body.classList.toggle('admin-sidebar-collapsed');try{localStorage.setItem('brew_admin_sidebar_collapsed',collapsed?'1':'0')}catch(e){}}
document.getElementById('menuBtn').setAttribute('aria-expanded',String(mobile?document.getElementById('sidebar').classList.contains('open'):!document.body.classList.contains('admin-sidebar-collapsed')));
});document.getElementById('overlay').addEventListener('click',()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('overlay').classList.remove('show');});
document.getElementById('search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#orderRows tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));});
try{if(!window.matchMedia('(max-width:820px)').matches&&localStorage.getItem('brew_admin_sidebar_collapsed')==='1')document.body.classList.add('admin-sidebar-collapsed')}catch(e){}
document.getElementById('menuBtn').setAttribute('aria-expanded',String(!document.body.classList.contains('admin-sidebar-collapsed')));
renderNotifications();setInterval(()=>{if(!document.hidden)refreshNotifications();},30000);if(window.lucide)lucide.createIcons();
</script></body></html>
